/* ---------- THE EYE (v29): the connoisseur’s daily test ----------
   Where, when, whose, how much, and which is the fake. Four games a day, each seeded by the date so everyone plays the same works,
   five rounds each (the games the record praises run five; Anthropeum’s ten drew the complaint that a daily is too long):
   WHERE & WHEN — works from the open collections (EYE_POOL: Cleveland, CC0, and the Art Institute of Chicago, placed by
   tools/gen_research.py through EYE_GEO) and the Library’s pictures (EYE_MADE); a pin on the globe and a year on the dial; 500 points
   for the place and 500 for the date on a connoisseur’s curve: the place scored against the museum’s own granularity (a city 40 km
   free, a dynasty or a country hundreds), the date against the museum’s own earliest–latest range (full marks inside it), the
   tolerance widening with the work’s distance from the present. A closer look is free; it zooms, it does not tell.
   THE HAMMER — sold lots from the Hammer: the catalogue line (artist, title, date, medium, house, room, sale date, the estimate
   where published) and the picture where the Library holds it; name the price with fees; points by the ratio (within 10% is full).
   THE HAND — a detail first, then more with every wrong name; four names of the same period; three tries (300, 200, 100).
   THE FORGER — three pairs: one is catalogued by the museum itself as a modern forgery, the other is its genuine kin; which?
   After every round the card teaches: the museum’s record, its own explanation and its page, the artist’s dossier, the tide that
   carries the artist, the lots in the Hammer. The result string to share; the streak and the best kept on the device; the week’s
   league among members (db collection scores/{self}: one document per member); the archive replays any day of the last sixty
   (scored, kept, not posted). A reading of the public record, never a route. Exposed: window.__EYE. */
const EYE_MODES=[['where','Where & when','works: the place on the globe, the year on the rail'],['history','The world','a battle, a wonder, a voyage: where and when, from a picture of the record'],['hammer','The hammer','sold lots: name the price with fees'],['hand','The hand','works: whose hand, from a detail'],['forger','The forger','pairs: one is a modern forgery; which?']];
const EYE_ZMAX=14;   /* the globe zooms to 14×: a pin on a city, not a country */
const EYE_N={where:5,history:5,hammer:5,hand:5,forger:3};const EYE_PER={where:1000,history:1000,hammer:1000,hand:300,forger:200};
const EYE_START=-3000,EYE_END=2026;
/* v34: the player chooses the length of a game (5, 10 or 15 rounds; the forger keeps its pairs) and may always ask for another round:
   the first game of the day at five rounds is the one the league counts; the longer games and the further rounds are scored and kept on
   the device */
const EYE_NS=[5,10,15];
function eyeN(mode){const n=+store.get('eye.n',5);const k=EYE_NS.includes(n)?n:5;return mode==='forger'?Math.max(3,Math.round(k*.6)):k;}
/* v34: the year rail is piecewise, with more room where more of the works were made, and ends at 2026; t runs 0–1000 */
const EYE_RAIL=[[-3000,0],[0,.16],[1000,.3],[1400,.42],[1600,.56],[1800,.72],[1900,.86],[2026,1]];
function eyeY2T(y){y=Math.max(EYE_START,Math.min(EYE_END,y));for(let i=1;i<EYE_RAIL.length;i++){const [y0,t0]=EYE_RAIL[i-1],[y1,t1]=EYE_RAIL[i];if(y<=y1)return Math.round((t0+(t1-t0)*(y-y0)/(y1-y0))*1000);}return 1000;}
function eyeT2Y(t){t=Math.max(0,Math.min(1000,t))/1000;for(let i=1;i<EYE_RAIL.length;i++){const [y0,t0]=EYE_RAIL[i-1],[y1,t1]=EYE_RAIL[i];if(t<=t1)return Math.round(y0+(y1-y0)*(t-t0)/(t1-t0));}return EYE_END;}
const eyeState={mode:'where',day:null,today:true,i:0,rounds:[],done:false,picks:[],pin:null,year:null,tries:0,revealed:false};
/* the day: the UTC date as a number; mulberry32 seeded by it; a seeded shuffle gives each day its works without repeats for pool/n days */
const eyeDay=()=>{const d=new Date();return Math.floor(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate())/86400000);};
const eyeIsoOf=day=>new Date(day*86400000).toISOString().slice(0,10);
const eyeDayIso=()=>eyeIsoOf(eyeDay());
function eyeRng(seed){let a=seed>>>0;return ()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
