/* years: "1889", "1911–12", "c. 1500", "5th–8th century", "600–575 BCE" → [y0, y1] */
const eyeYear=s=>{s=String(s||'');const bc=/\bBCE?\b/i.test(s);const cm=[...s.matchAll(/(\d{1,2})(?:st|nd|rd|th)\s*(?:[–-]\s*(\d{1,2})(?:st|nd|rd|th)\s*)?centur/gi)];if(cm.length&&!/\d{3,4}/.test(s)){const a=+cm[0][1],b=+(cm[0][2]||cm[0][1]);return bc?[-(b*100),-((a-1)*100+1)]:[(a-1)*100+1,b*100];}const m=s.match(/(\d{3,4})/g);if(!m)return null;let ys=m.map(Number).filter(y=>y>0&&y<=2030);if(!ys.length)return null;if(bc)ys=ys.map(y=>-y);return [Math.min(...ys),Math.max(...ys)];};
