function eyePicHtml(w,alt){const sh=eyeSheet(w);const hi=w.hi||(w.src==='aic'&&/\/full\/843,\//.test(w.img||'')?w.img.replace('/full/843,/','/full/1686,/'):'');const inner=sh?`<canvas class="eye-cv" data-eye-sheet="${esc(sh.file)}" data-eye-crop="${sh.x},${sh.y},${sh.w},${sh.h}" width="${sh.w}" height="${sh.h}" role="img" aria-label="${esc(alt)}"></canvas>`:`<img src="${esc(w.img)}" alt="${esc(alt)}" loading="eager" decoding="async" referrerpolicy="no-referrer" data-eye-img${hi?` data-hi="${esc(hi)}"`:''}>`;return `<div class="eye-frame">${inner}</div>`;}
