const eyeSheetCache={};
function eyeDrawSheets(body){body.querySelectorAll('canvas[data-eye-sheet]').forEach(cv=>{const file=cv.dataset.eyeSheet;const [x,y,w,h]=cv.dataset.eyeCrop.split(',').map(Number);const paint=im=>{try{if(typeof window.CanvasRenderingContext2D!=='function')return;const c=cv.getContext('2d');c.drawImage(im,x,y,w,h,0,0,w,h);cv.classList.add('ready');}catch(e){}};let im=eyeSheetCache[file];if(im&&im.complete&&im.naturalWidth){paint(im);return;}if(!im){im=new Image();im.decoding='async';eyeSheetCache[file]=im;im.src=file;}im.addEventListener('load',()=>paint(im),{once:true});im.addEventListener('error',()=>{const fig=cv.closest('figure');if(fig&&!fig.querySelector('.eye-nopic')){fig.classList.add('none');fig.insertAdjacentHTML('beforeend','<div class="eye-nopic"><span>The sheet did not load. Pass this round without penalty.</span><button class="lk" data-eye-pass>Pass</button></div>');const b=fig.querySelector('[data-eye-pass]');if(b)b.addEventListener('click',()=>{const w=eyeState.picks[eyeState.i];if(!eyeState.revealed){eyeState.rounds.push({total:0,passed:true,id:w?w.id:''});eyeState.revealed=true;}eyeNext();eyeRound();});}},{once:true});});}
