function eyeImgGuard(body){body.querySelectorAll('[data-eye-img]').forEach(im=>{const ready=()=>{im.classList.add('ready');const fig=im.closest('figure');if(fig){fig.classList.remove('none');const n=fig.querySelector('.eye-nopic');if(n)n.remove();}};if(im.complete&&im.naturalWidth)ready();else{im.addEventListener('load',ready,{once:true});/* v34: a museum's server that does not answer in nine seconds counts as a failure, so the round can be passed; a late arrival still shows */setTimeout(()=>{if(im.isConnected&&!(im.complete&&im.naturalWidth))im.dispatchEvent(new Event('error'));},9000);}});body.querySelectorAll('[data-eye-img]').forEach(im=>im.addEventListener('error',()=>{const fig=im.closest('figure');if(!fig||fig.querySelector('.eye-nopic'))return;fig.classList.add('none');fig.insertAdjacentHTML('beforeend','<div class="eye-nopic"><span>The museum’s picture did not load (its server, not the terminal). Pass this round without penalty.</span><button class="lk" data-eye-pass>Pass</button></div>');const b=fig.querySelector('[data-eye-pass]');if(b)b.addEventListener('click',()=>{const w=eyeState.picks[eyeState.i];if(!eyeState.revealed){eyeState.rounds.push({total:0,passed:true,id:w?w.id:''});eyeState.revealed=true;}eyeNext();eyeRound();});},{once:true}));}
